sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // 1. Operation Theatre Room Category check
    if (!current.operation_theatre.nil()) {
        var roomCat = current.operation_theatre.room_category.toString();
        if (roomCat != 'Operation Theatre') {
            gs.addErrorMessage('Invalid Room: The selected room category must be "Operation Theatre".');
            current.setAbortAction(true);
            return;
        }
    }

    // 2. Validate Surgeon Order and Consent Complete before Approved ('2' = Approved)
    if (current.getValue('status') == '2' || current.status == 2) {
        var surgeonOrder = current.getValue('surgeon_order') == '1' || current.getValue('surgeon_order') == true;
        var consentComplete = current.getValue('consent_complete') == '1' || current.getValue('consent_complete') == true;

        if (!surgeonOrder || !consentComplete) {
            var missing = [];
            if (!surgeonOrder) missing.push('Surgeon Order');
            if (!consentComplete) missing.push('Consent Complete');

            gs.addErrorMessage('Cannot approve OT Booking: ' + missing.join(' and ') + ' must both be checked before approval.');
            current.setAbortAction(true);
            return;
        }
    }

})(current, previous);
